INSERT INTO questions (questionnaire_id, position, question_code, text, hint, type, options_json, is_required, max_choices, correct_answer_json)
SELECT q.id, v.position, v.question_code, v.text, v.hint, v.type, v.options_json::jsonb, v.is_required, v.max_choices, v.correct_answer_json::jsonb
FROM questionnaires q
CROSS JOIN (VALUES
(1, 'ai_frequency', 'Как часто вы используете нейросети?', NULL, 'SINGLE_CHOICE',
 '["Не использую","Пробовал несколько раз","Использую время от времени","Использую каждую неделю","Использую почти ежедневно"]', true, NULL, NULL),
(2, 'ai_tools', 'Какими инструментами уже пользовались?', 'Можно выбрать несколько вариантов', 'MULTIPLE_CHOICE',
 '["ChatGPT","Claude","Gemini","Perplexity","Генераторы изображений","Генераторы видео","Конструкторы сайтов и приложений","Сервисы автоматизации","Другие","Пока никакими"]', true, NULL, NULL),
(3, 'ai_tasks', 'Для каких задач применяете AI?', 'Можно выбрать несколько вариантов', 'MULTIPLE_CHOICE',
 '["Тексты и контент","Изображения и дизайн","Видео","Продажи и маркетинг","Аналитика","Автоматизация","Создание сайтов и приложений","Работа с документами","Пока не применяю","Другое"]', true, NULL, NULL),
(4, 'ai_result', 'Какой результат уже получали?', NULL, 'SINGLE_CHOICE',
 '["Пока никакого","Сэкономил время","Улучшил качество работы","Сделал учебный проект","Применил в рабочей задаче","Выполнил задачу для клиента","Получил доход с помощью AI"]', true, NULL, NULL),
(5, 'ai_self_score', 'Оцените свои навыки работы с AI от 1 до 10', '1 — совсем не умею, 10 — уверенно применяю', 'SCALE', '{"min":1,"max":10}', true, NULL, NULL),
(6, 'goal_main', 'Зачем вы идёте в школу?', 'Можно выбрать до трёх вариантов', 'MULTIPLE_CHOICE',
 '["Применять AI в текущей работе","Автоматизировать бизнес","Увеличить доход","Освоить новую профессию","Начать оказывать AI-услуги","Создавать контент","Создавать сайты и приложения","Создать AI-ассистента","Создать AI-продукт","Разобраться в нейросетях для себя","Другое"]', true, 3, NULL),
(7, 'goal_result', 'Какой конкретный результат хотите получить к концу обучения?', 'Опишите своими словами', 'LONG_TEXT', NULL, true, NULL, NULL),
(8, 'goal_task', 'Какую реальную задачу хотите решить с помощью AI?', 'Опишите задачу из своей работы или бизнеса', 'LONG_TEXT', NULL, true, NULL, NULL),
(9, 'goal_success', 'Как поймёте, что обучение прошло успешно?', NULL, 'SINGLE_CHOICE',
 '["Начну регулярно применять AI","Сэкономлю время","Автоматизирую процесс","Создам готовый проект","Соберу портфолио","Найду первого клиента","Получу первый доход","Запущу AI-продукт","Другое"]', true, NULL, NULL),
(10, 'time_week', 'Сколько времени готовы уделять обучению в неделю?', NULL, 'SINGLE_CHOICE',
 '["До 2 часов","2–4 часа","5–7 часов","Более 7 часов"]', true, NULL, NULL),
(11, 'obstacles', 'Что может помешать обучению?', 'Можно выбрать несколько вариантов', 'MULTIPLE_CHOICE',
 '["Нехватка времени","Рабочая нагрузка","Сложность материала","Недостаток практики","Технические сложности","Сложно сохранять регулярность","Пока не вижу препятствий","Другое"]', true, NULL, NULL),
(12, 'test_1', 'Что сильнее всего влияет на качество ответа текстовой AI-модели?', NULL, 'TEST_SINGLE_CHOICE',
 '["Ясная задача, контекст, ограничения и формат","Длина запроса","Вежливость формулировки","Количество попыток"]', true, NULL, '"Ясная задача, контекст, ограничения и формат"'),
(13, 'test_2', 'Что делать, если уверенный ответ AI содержит важный факт?', NULL, 'TEST_SINGLE_CHOICE',
 '["Проверить по надёжному источнику","Сразу использовать — модель уверена","Переспросить ту же модель","Ничего, факты всегда верны"]', true, NULL, '"Проверить по надёжному источнику"'),
(14, 'test_3', 'Какой промпт полезнее для бизнес-задачи?', NULL, 'TEST_SINGLE_CHOICE',
 '["Промпт с целью, аудиторией, контекстом, форматом и ограничениями","Максимально короткий промпт","Промпт из одного ключевого слова","Промпт на английском языке"]', true, NULL, '"Промпт с целью, аудиторией, контекстом, форматом и ограничениями"'),
(15, 'test_4', 'Для чего особенно полезна генерация изображений?', NULL, 'TEST_SINGLE_CHOICE',
 '["Визуальные концепты, креативы, иллюстрации и прототипы","Только для развлечения","Для замены фотографа во всех задачах","Для точных технических чертежей"]', true, NULL, '"Визуальные концепты, креативы, иллюстрации и прототипы"'),
(16, 'test_5', 'Что означает автоматизация AI-задачи?', NULL, 'TEST_SINGLE_CHOICE',
 '["Связать триггер, данные, AI-обработку и действие","Писать запросы быстрее","Использовать несколько моделей сразу","Купить платную подписку"]', true, NULL, '"Связать триггер, данные, AI-обработку и действие"'),
(17, 'test_6', 'Какой признак показывает практическую ценность AI?', NULL, 'TEST_SINGLE_CHOICE',
 '["Экономия времени или денег либо улучшение результата","Красивый интерфейс сервиса","Популярность инструмента","Количество сгенерированных вариантов"]', true, NULL, '"Экономия времени или денег либо улучшение результата"'),
(18, 'test_7', 'Что важнее для первого заработка на AI-услуге?', NULL, 'TEST_SINGLE_CHOICE',
 '["Решить конкретную проблему клиента и показать результат","Знать максимум инструментов","Иметь платные подписки","Сделать красивое портфолио без заказов"]', true, NULL, '"Решить конкретную проблему клиента и показать результат"')
) AS v(position, question_code, text, hint, type, options_json, is_required, max_choices, correct_answer_json)
WHERE q.type = 'entrance'
  AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.questionnaire_id = q.id);
